import{_ as n,o as e,c as a,S as o}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse('{"title":"Chrome扩展和Web Page 进行通讯","description":"由于 WEB 页面本身受到浏览器的安全策略限制,而且 Content Scripts 和页面本身并不共享环境变量.我们很多时候都是\\n通过 DOM 去注入 JS 代码到当前页面上.因为同源策略的原因不得不把有些操作发回到 Background…","frontmatter":{"title":"Chrome扩展和Web Page 进行通讯","date":"2015-8-25 19:54","comments":true,"archives":2015,"tags":["chrome"]},"headers":[],"relativePath":"posts/2015-08-25-communication-between-extensions-and-web-page/index.md","filePath":"posts/2015/2015-08-25-Communication-between-extensions-and-web-page.md"}'),p={name:"posts/2015-08-25-communication-between-extensions-and-web-page/index.md"};function t(r,s,l,c,i,d){return e(),a("div",null,[...s[0]||(s[0]=[o(`<p>由于 WEB 页面本身受到浏览器的安全策略限制,而且 Content Scripts 和页面本身并不共享环境变量.我们很多时候都是 通过 DOM 去注入 JS 代码到当前页面上.因为同源策略的原因不得不把有些操作发回到 Background 进行处理,因为 Background 没有任何限制,可以拥有完整的 Chrome 的 API 权限.</p><h2 id="通过-content-scripts-中转" tabindex="-1">通过 Content Scripts 中转 <a class="header-anchor" href="#通过-content-scripts-中转" aria-label="Permalink to &quot;通过 Content Scripts 中转&quot;">​</a></h2><p>第一种通讯方式是通过 Web API <a href="https://developer.mozilla.org/en-US/docs/Web/API/Window/postMessage" target="_blank" rel="noreferrer">postMessage</a> 发送消息,然后在 Content Scripts 监听 message 事件捕捉消息发送回 Background 这种方式适合单向通讯,只从 web page 发送数据到 Background 或者 Background 发送给 web page 如果双向通讯的话就很不方便了 因为 Content Scripts 和 web page 共享 window 会造成事件重复绑定的.</p><h2 id="使用-chrome-api" tabindex="-1">使用 Chrome API <a class="header-anchor" href="#使用-chrome-api" aria-label="Permalink to &quot;使用 Chrome API&quot;">​</a></h2><p>首先在 manifest.json 里声明权限</p><div class="language-json line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#032F62;">&quot;externally_connectable&quot;</span><span style="color:#24292E;">: {</span></span>
<span class="line"><span style="color:#005CC5;">  &quot;matches&quot;</span><span style="color:#24292E;">: [</span><span style="color:#032F62;">&quot;*://*.example.com/*&quot;</span><span style="color:#24292E;">]</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>声明要通讯的网页的网址,然后和 Content Script 一样建立通讯</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> port </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> chrome.runtime.</span><span style="color:#6F42C1;">connect</span><span style="color:#24292E;">(chrome_id, { name: </span><span style="color:#032F62;">&#39;abc&#39;</span><span style="color:#24292E;"> });</span></span>
<span class="line"><span style="color:#24292E;">port.</span><span style="color:#6F42C1;">postMessage</span><span style="color:#24292E;">({</span></span>
<span class="line"><span style="color:#24292E;">  method: </span><span style="color:#032F62;">&#39;rpc_data&#39;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">  data: parameter</span></span>
<span class="line"><span style="color:#24292E;">});</span></span>
<span class="line"><span style="color:#24292E;">port.onMessage.</span><span style="color:#6F42C1;">addListener</span><span style="color:#24292E;">(</span><span style="color:#D73A49;">function</span><span style="color:#24292E;"> (</span><span style="color:#E36209;">response</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#6F42C1;">  SetMessage</span><span style="color:#24292E;">(response[</span><span style="color:#005CC5;">0</span><span style="color:#24292E;">], response[</span><span style="color:#005CC5;">1</span><span style="color:#24292E;">]);</span></span>
<span class="line"><span style="color:#24292E;">});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>关键是 Background 监听消息的接收,必须使用 <code>chrome.runtime.onConnectExternal.addListener</code> 而不是 <code>chrome.runtime.onConnect.addListener</code> 后者是接收 Content Script 消息的,前者是 接收 Web Page 消息的. 这样便实现了 Web Page 和 Background 之间的双向通讯, Web Page 不能完成的事情交给 Background 来处理即可.</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://developer.chrome.com/extensions/messaging#external-webpage" target="_blank" rel="noreferrer">官方文档</a></p>`,11)])])}const u=n(p,[["render",t]]);export{b as __pageData,u as default};
